geekmaxi.com.apply:
const coupon = document.querySelector('#discount_name');
let lang = '';

switch (document.documentElement.lang) {
  case 'de-de':
    lang = 'bestellung';
    break;
  case 'nl-nl':
    lang = 'bestelling';
    break;
  default:
    lang = 'order'
}

const form_data = new FormData();

form_data.append('discount_name', coupon.value);
form_data.append('submitDiscount', '');
form_data.append('submitAddDiscount', '');

fetch('https://www.geekmaxi.com/'+lang, {
	method: 'post',
	body: form_data
})
.then(res => location.reload())
.catch(e => {});

